2.  **`applyTextFormatting` Function:**

    ```javascript
    //script.js lines #2266-2315
    function applyTextFormatting(command, isUnderline, isItalic) {

      let selectedText = window.getSelection(); //get text selected
      if (!selectedText.toString()) {
        console.error('No text is currently selected.');
        return;  // Exit if no text selected
      }
      let selectedText_text = selectedText.toString();
      let switch_txt;
      switch (command) {
        case 'bold':
          switch_txt = selectedText_text.replace(/<b>(.*?)<\/b>/g, '$1').trim(); //remove existing bold
          if (switch_txt === selectedText_text)
          {
             switch_txt = `<b>${selectedText_text}</b>`; //add bold if it doesnt exist
          }
            break;
        case 'removeBlankLinesFromText':
          switch_txt = selectedText_text.replace(/\n\s*\n/g, '\n').trim();

            break;
        case 'removeDuplicateLines':
          const lines = selectedText_text.split('\n');
          const set = new Set(lines);  // Use Set for uniqueness
          switch_txt = [...set].join('\n');

            break;
        case 'removeInlineBreaks':
           switch_txt = selectedText_text.replace(/[\r\n]+/gm, ' ').trim() //replace enter with space
            break;
            case 'removeParagraphs':
           switch_txt = selectedText_text.replace(/<p>(.*?)<\/p>/g, '$1').trim() //replace p with space
            break;
        default:
            switch_txt = selectedText_text;
            break;
      }
        if (isUnderline)
        {
            switch_txt = selectedText_text.replace(/<u>(.*?)<\/u>/g, '$1').trim(); //remove existing bold
          if (switch_txt === selectedText_text)
          {
             switch_txt = `<u>${selectedText_text}</u>`; //add bold if it doesnt exist
          }
        }
         if (isItalic)
        {
            switch_txt = selectedText_text.replace(/<i>(.*?)<\/i>/g, '$1').trim(); //remove existing bold
          if (switch_txt === selectedText_text)
          {
             switch_txt = `<i>${selectedText_text}</i>`; //add bold if it doesnt exist
          }
        }
      range.deleteContents(); //remove current selected text
      range.insertNode(createTexNode(switch_txt)); //place formatted text
      selectedText.addRange(range); //add back selection
    }
    ```
    *   This function manages the core text formatting logic.
    *   First it gets the `selectedText`.
    *   Then it uses a switch to determine if the 'bold' command needs to run.
    *   If not bold, it checks if underline or italic needs to run.
    *   It removes/adds bold/underline/italic and removes it, depending on if it exists.
    *   It removes the selected text and replaces with the formatted text.

3.  **`formatBulletsAndNumbers` Function**

    ```javascript
     //script.js #2110-2157
    function formatBulletsAndNumbers(content) {
        let isBulletedList = false;
        let isNumberedList = false;

      let trimedInline = content.trim();
      if (trimedInline.startsWith('<ul>') && trimedInline.endsWith('</ul>')) {
            isBulletedList = true;
      }
       else if (/[1-9]\./g.test(trimedInline))
       {
          isNumberedList = true;
       }

      else if (trimedInline.startsWith('<ol>') && trimedInline.endsWith('</ol>')) {
         isNumberedList = true;
      }

    let formattedContent;

        if (isBulletedList) {
        formattedContent = '<div>' + trimedInline.substring(4, trimedInline.length - 5).trim().replace(/<li>(.*?)<\/li>/g, '$1<br>') + '</div>';

    } else if (isNumberedList) {
         let startNumber = parseInt(trimedInline.substring(4, trimedInline.indexOf('.')).trim(), 10); // Extract starting number
         formattedContent =
        '<div>' + trimedInline.substring(trimedInline.indexOf('>')+1, trimedInline.length - 5).trim().replace(/<li>(.*?)<\/li>/g, (match, item) => {
          const result = `${item}<br>`;
          startNumber++; // Increment for next item
          return result;
        }) +
        '</div>';
    }
    else {

        formattedContent = `<ul><li>${content.replace(/<br\s*\/?>/gi, "</li><li>")}</li></ul>`;
      }
      return formattedContent;
    }

    ```

    *   This function handles the creation and removal of bulleted and numbered lists.
    *   It checks if the `content` is already a bulleted or numbered list.
    *   If it's an existing list, it converts the list items (`<li>`) to simple `<div>` elements with `<br>` for line breaks (effectively *removing* the list formatting).
    *    If the list is numbered, it maintains a start number, to increment for the next list item.
    *   If it's *not* an existing list, it wraps the content in `<ul><li>...</li></ul>` tags to create a bulleted list. It also replaces `<br>` tags with `</li><li>` to handle existing line breaks correctly.
    *   Crucially, the result is a *string* containing the HTML. This string is what's used to update the content.

4.  **`insertNode`**

