      },
      body: JSON.stringify(requestBody),
    });

    if (!response.ok) {
      // Handle HTTP errors more gracefully.  Get text if possible.
      const errorText = await response.text();
      throw new Error(`AI request failed with status ${response.status}: ${errorText}`);
    }

    const data = await response.json();

    // 5. Process the response based on the model.
    let aiResponseText;

    if (data.response === undefined) {
        throw new Error("The 'response' key is missing in the server's reply.");
    }
    if (selectedModel.startsWith("gemini")) {
        if (data.response && typeof data.response === 'object' && data.response.hasOwnProperty('candidates'))
        {
            // Check if 'candidates' exists and has at least one element
            if (data.response.candidates && data.response.candidates.length > 0)
            {
                aiResponseText = data.response.candidates[0]?.content?.parts?.[0]?.text;
            }
        }
        else {
            aiResponseText = data.response.text //For regular gemini
        }
    } else if (selectedModel.startsWith("mistral") || selectedModel.startsWith("nvidia/nemotron") || selectedModel.startsWith("google/gemma-2")) { //Handle Mistral, etc.
        if (data.response && typeof data.response === 'object')
        {
          aiResponseText = data.response.response
        }
        else{
          aiResponseText = "ERROR"
        }
    }
     else if(selectedModel == "gemini-2.0-flash-exp"){
          aiResponseText = data.response.text //for gemini-2.0-flash-exp
        }
    else {
      // Fallback for other models (or handle as an error)
      aiResponseText = data.response; // Default fallback
    }

    if (!aiResponseText) {
       // Handle the case where the response is missing or invalid.
       throw new Error("Received an empty or invalid AI response.");
    }


    // 6. Add AI's message and update UI.
    const aiMessageObj = { user: 'bot', message: aiResponseText };
    addMessage(aiResponseText, false);
    appDataManager.addMessageToCurrentChat(aiMessageObj);

    // 7. Debounced save (more efficient).
    appDataManager.saveAllChatsToServer(); //Now it is debounced, no need for await

  } catch (error) {
    console.error('Error sending message:', error);
    // Display a user-friendly error message.
    addMessage(`Error: ${error.message}`, false); // Add an error message to the chat
    appDataManager.addMessageToCurrentChat({ user: 'bot', message: `Error: ${error.message}` }); //and save to local storage
    appDataManager.saveAllChatsToServer(); //save error to server

  }
}

```

Key Changes and Explanations:

* **Snake Case for `file_id`:**  Your Python code uses `file_id` (snake_case) in the request body.  JavaScript conventionally uses camelCase (`fileId`).  The revised code uses `file_id` in the `requestBody` to match the Python endpoint's expectation.  This is *crucial* for the file ID to be correctly received on the server.
* **Model-Specific Response Handling:** The code now checks the `selectedModel` *before* processing the response.  This allows you to correctly extract the AI's response text from the potentially nested structures returned by different models (Gemini, Mistral, etc.). This directly addresses your original issue. The logic closely mirrors how you handle different models in your `app.py`.
* **Error Handling:**
    * **HTTP Error Handling:**  If `response.ok` is false (meaning a 4xx or 5xx error), the code now tries to get the error text from the response (`await response.text()`) and includes it in the error message.  This gives you more information about what went wrong on the server.
    * **Missing/Invalid Response:**  The code explicitly checks if `aiResponseText` is empty or undefined *after* attempting to extract it. This handles cases where the server returns a response, but it's not in the expected format.
    * **User-Friendly Error Message:** Instead of just an `alert`, the error message is now added to the chat UI, providing a better user experience.  It also saves the error to local storage.
* **Debounced Saving:** The `appDataManager` already has a `saveAllChatsToServer` method that uses debouncing. Calling the `await appDataManager.saveAllChatsToServer()` after *every* single message exchange is inefficient. Instead, call `appDataManager.saveAllChatsToServer()` without `await`, which uses its internal debounce timer. This significantly reduces the number of server requests.
* **Consistent Message Objects:** Create `messageObj` and `aiMessageObj` to ensure consistent data structures when adding messages to local storage.
* **Readability:** Improved variable names (e.g., `aiResponseText`) and comments make the code easier to understand.
* **webscrapeIndicator:** I added the logic for sending the `webscrapeIndicator` to the backend.

